Item.method_code:
const itemNode = window.item;
const lockedById = aras.getItemProperty(itemNode, 'locked_by_id');
const isItemLockedByMe = aras.user.id === lockedById;
const isInEditMode = ArasModules.item.isEditState('ItemType', itemNode.id);
if (isItemLockedByMe && !isInEditMode) {
	return { disabled: false };
}

const { commandFactory } = options;
const claimCommand = commandFactory('LockItem', { itemNode });
const disabled = !claimCommand.canExecute();

return { disabled };
